interface Env {
  AUDIO: R2Bucket
  UPLOAD_TOKEN: string
}

const sha256Hex = async (buf: ArrayBuffer) =>
  [...new Uint8Array(await crypto.subtle.digest("SHA-256", buf))].map((b) => b.toString(16).padStart(2, "0")).join("")

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url)

    // Variant B: a plain Worker route that accepts the PUT and writes through the binding.
    if (url.pathname.startsWith("/upload/") && request.method === "PUT") {
      if (url.searchParams.get("token") !== env.UPLOAD_TOKEN) {
        return new Response("forbidden", { status: 403 })
      }

      const key = decodeURIComponent(url.pathname.slice("/upload/".length))
      const started = Date.now()
      const object = await env.AUDIO.put(key, request.body, {
        httpMetadata: { contentType: request.headers.get("content-type") ?? "application/octet-stream" },
      })

      return Response.json({ key, size: object.size, ms: Date.now() - started })
    }

    if (url.pathname.startsWith("/check/")) {
      const object = await env.AUDIO.get(decodeURIComponent(url.pathname.slice("/check/".length)))

      if (object == null) {
        return new Response("missing", { status: 404 })
      }

      const buf = await object.arrayBuffer()
      return Response.json({ size: object.size, sha256: await sha256Hex(buf), contentType: object.httpMetadata?.contentType })
    }

    return new Response("ok")
  },
}
