import modal

app = modal.App("nagara-spike-upload")

image = modal.Image.debian_slim(python_version="3.12").pip_install("httpx").add_local_file("r3-long.ogg", "/audio/r3-long.ogg")


@app.function(image=image, timeout=300)
def upload(url: str) -> dict:
    import hashlib
    import time

    import httpx

    data = open("/audio/r3-long.ogg", "rb").read()
    started = time.monotonic()
    response = httpx.put(url, content=data, headers={"content-type": "audio/ogg"}, timeout=240)

    return {
        "status": response.status_code,
        "body": response.text[:400],
        "seconds": round(time.monotonic() - started, 2),
        "size": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }
