// usage: node proxy.mjs <listen-port> <dev-server-port>
// Cloudflare's edge reserves /cdn-cgi/*, so the tunnel carries /s3/* and this restores the path and the localhost Host the URL was signed for.
import http from "node:http"

const [listen, target] = process.argv.slice(2).map(Number)

http
  .createServer((req, res) => {
    const path = req.url.startsWith("/s3/") ? `/cdn-cgi/local/r2/s3/${req.url.slice(4)}` : req.url
    const upstream = http.request(
      { host: "127.0.0.1", port: target, method: req.method, path, headers: { ...req.headers, host: `localhost:${target}` } },
      (up) => {
        res.writeHead(up.statusCode, up.headers)
        up.pipe(res)
      },
    )

    upstream.on("error", (error) => {
      res.writeHead(502)
      res.end(String(error))
    })
    req.pipe(upstream)
  })
  .listen(listen, "127.0.0.1")
EOF
cat > worker/tunnel-url.mjs <<'EOF'
// usage: node tunnel-url.mjs <dev-server-port> <tunnel-host> <bucket> <key>
// Presigns for localhost (what the dev server checks) and swaps in the tunnel host and the /s3 prefix.
import { execFileSync } from "node:child_process"

const [port, tunnel, bucket, key] = process.argv.slice(2)
const signed = new URL(execFileSync("node", ["presign.mjs", `http://localhost:${port}/cdn-cgi/local/r2/s3`, bucket, key], { encoding: "utf8" }).trim())

console.log(`https://${tunnel}/s3/${signed.pathname.slice("/cdn-cgi/local/r2/s3/".length)}${signed.search}`)
EOF
setsid node worker/proxy.mjs 8892 5199 > proxy-vite.log 2>&1 < /dev/null & echo $! > proxy-vite.pid
setsid cloudflared tunnel --no-autoupdate --url http://localhost:8892 > cf-proxy-vite.log 2>&1 < /dev/null & echo $! > cf-proxy-vite.pid
for i in $(seq 1 30); do H=$(grep -o 'https://[a-z0-9-]*\.trycloudflare\.com' cf-proxy-vite.log | head -1); [ -n "$H" ] && break; sleep 1; done; H=${H#https://}; echo $H > proxy-vite.host
for i in $(seq 1 40); do c=$(curl -s -o /dev/null -w '%{http_code}' https://$H/); [ "$c" = 200 ] && break; sleep 3; done; echo root=$c

